export function printable(cp){ return cp===0x20 || !NP.test(String.fromCodePoint(cp)); }
export function pyStrRepr(s){
  const cps=[...s].map(c=>c.codePointAt(0));
  // NOTE: [...s] on lone surrogates yields the lone surrogate; codePointAt gives it
  const hasS = s.includes("'"), hasD = s.includes('"');
  const q = (hasS && !hasD) ? '"' : "'";
  let out=q;
  for(const cp of cps){
    if(cp===0x5c){ out+='\\\\'; continue; }
    if(String.fromCodePoint(cp)===q){ out+='\\'+q; continue; }
    if(cp===0x0a){ out+='\\n'; continue; }
    if(cp===0x0d){ out+='\\r'; continue; }
    if(cp===0x09){ out+='\\t'; continue; }
    if(printable(cp)) { out+=String.fromCodePoint(cp); continue; }
    if(cp<0x100) out+='\\x'+cp.toString(16).padStart(2,'0');
    else if(cp<0x10000) out+='\\u'+cp.toString(16).padStart(4,'0');
    else out+='\\U'+cp.toString(16).padStart(8,'0');
  }
  return out+q;
}
export function pyFloatRepr(v){
  if(Number.isNaN(v)) return 'nan';
  if(v===Infinity) return 'inf';
  if(v===-Infinity) return '-inf';
  const neg = v<0 || Object.is(v,-0);
  const a = Math.abs(v);
  let digits, decpt;
  if(a===0){ digits='0'; decpt=1; }
  else {
    const t=a.toString(); let m;
    if((m=/^(\d+)\.(\d+)e([+-]\d+)$/.exec(t))){ digits=(m[1]+m[2]).replace(/0+$/,'')||'0'; decpt=parseInt(m[3],10)+m[1].length; }
    else if((m=/^(\d+)e([+-]\d+)$/.exec(t))){ digits=m[1].replace(/0+$/,'')||'0'; decpt=parseInt(m[2],10)+m[1].length; }
