      if(ip==='0'){ let z=0; while(z<fp.length&&fp[z]==='0')z++; digits=fp.slice(z).replace(/0+$/,''); decpt=-z; }
      else { digits=(ip+fp).replace(/0+$/,'')||'0'; decpt=ip.length; } }
    else { const ip=/^(\d+)$/.exec(t)[1]; digits=ip.replace(/0+$/,'')||'0'; decpt=ip.length; }
