export function pyRepr(x){
  switch(x.t){
    case 'int': return x.v;
    case 'float': return pyFloatRepr(x.v);
    case 'str': return pyStrRepr(x.v);
    case 'bool': return x.v?'True':'False';
    case 'null': return 'None';
    case 'arr': return '['+x.v.map(pyRepr).join(', ')+']';
